B.h

    class B {
    public:
        virtual void function() = 0;
    }

A.h

    #include "B.h"

    class A {
    public:
        // something

    private:
        B name;
    }

B_Implementation.h

    #include "B.h"

    class B_Implementation : public B {
    public:
        void function() {};
